									B.DIVISION_ID
									,B.VERSION_NO
									,B.CUTOFF_TYPE
									,B.CUTOFF_YYYYMMDD
									,B.PROJECT_CODE
									,B.SCM_SITE_ID
									,B.ITEM_ID
									,B.DOM_EXP
									,B.FCST_TYPE
