        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('WH_BOH_REQ', 'W/H BOH(Req)', 'A', 'Y', '219,229,241', 'Y', 11);
